import nl.dexanddice.solsurvivor.core.WaveLogWriter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Copies the Fortis Colosseum's state as a Sol Survivor link (design spec 2026-10-14-runelite-plugin-design.md). It only
 * reads the game and exports: it draws nothing in the game, neither tiles nor prayers nor plans, as Jagex's rules for
 * third-party clients require. The link goes to the clipboard from the side panel or a hotkey, and the player pastes it
 * into the site. While Minimus offers his three modifiers, the panel's "Open in recommender" opens the site's modifier
 * pick in the browser with them filled in (core.PickPayload); the offers ride in the link's hash, which the browser
 * keeps to itself.
 *
 * This class passes the game's events to ColosseumTracker, which holds the logic and is tested without RuneLite, and
 * reads the arena on the client thread when a link is asked for. With "Record wave log" on it also records each wave it
 * saw start, a tick at a time, in a WaveLog that keeps the waves since the plugin started and that the panel copies as
 * JSON for the site's wave reviewer, any of them picked from a list, or every wave of the newest run in one paste
 * (RunLogWriter).
 *
 * It sends nothing anywhere: a bad plan is reported from the site's own page.
 */
@PluginDescriptor(
	name = "Sol Survivor",
	description = "Copies the Fortis Colosseum's state as a Sol Survivor link. Draws nothing in the game.",
	tags = {"fortis", "colosseum", "sol", "planner", "export"}
)
public class SolSurvivorPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SolSurvivorPlugin.class);

	/** The script that fills the modifier selector, with the three on offer and the mask of those taken. */
	private static final int SCRIPT_MODIFIER_SELECT_INIT = 4931;
	/** The option picked in the selector, 1 to 3, read when Minimus leaves. */
	private static final int VARBIT_MODIFIER_SELECTED = 9788;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SolSurvivorConfig config;

	private final ColosseumTracker tracker = new ColosseumTracker();
	private boolean inColosseum;
	/** The link of the current wave's first tick, taken as it happens, since the player cannot press a key that fast. */
	private String waveStartLink;
	/** The same link's payload, which the wave's log starts with. */
	private String waveStartState;
	/** The log of the wave under way, or of the last one until the next starts, and the past ones; on the client thread only. */
	private final WaveLog waveLog = new WaveLog();

	private SolSurvivorPanel panel;
	private NavigationButton navButton;
	/** What the panel last showed, so that it is redrawn only when that changes rather than every tick. */
	private boolean shownInColosseum;
	private boolean shownWaveStart;
	private String shownWaveLog;
	private List<SolSurvivorPanel.LogChoice> shownLogs = new ArrayList<>();
	private boolean shownOffers;

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.copyHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			copyCurrent(false);
		}
	};

	@Provides
	SolSurvivorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SolSurvivorConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new SolSurvivorPanel(this::openWaveStart, () -> copyCurrent(true), this::openRecommender, this::copyWaveLog, this::copyRun);
		navButton = NavigationButton.builder()
			.tooltip("Sol Survivor")
			.icon(SolSurvivorPanel.icon())
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		keyManager.registerKeyListener(hotkeyListener);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		clientToolbar.removeNavigation(navButton);
		tracker.reset();
		waveLog.clear();
		inColosseum = false;
		waveStartLink = null;
		waveStartState = null;
		shownInColosseum = false;
		shownWaveStart = false;
		shownWaveLog = null;
		shownLogs = new ArrayList<>();
		shownOffers = false;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		// Logged out, hopping or logging in again: the run is over for the plugin, whose next tick may be far off.
		GameState state = e.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.LOGGING_IN || state == GameState.HOPPING)
		{
			leave();
		}
	}

	/** "Record wave log" switched off drops the log at once, and the panel shows the setting as it is, in or out of the arena. */
	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!SolSurvivorConfig.GROUP.equals(e.getGroup()) || !"recordWaveLog".equals(e.getKey()))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (!config.recordWaveLog())
			{
				waveLog.clear();
				waveLog.discardPending();
			}
			updatePanel();
		});
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (inColosseum && e.getType() == ChatMessageType.GAMEMESSAGE)
		{
			tracker.onGameMessage(e.getMessage(), client.getTickCount());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned e)
	{
		NPC npc = e.getNpc();
		tracker.onNpcSpawned(npc.getIndex(), npc.getId(), client.getTickCount());
	}

	/**
	 * An actor started an animation. For an NPC it may be an attack, which times its next one: the event, unlike the
	 * animation read each tick, also marks an attack that repeats the one before. The player's go in the wave log too, so
	 * that each of their attacks is there.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		Actor actor = e.getActor();
		if (inColosseum && actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			tracker.onNpcAnimation(npc.getIndex(), npc.getId(), npc.getAnimation(), client.getTickCount());
			// Only for a log being kept: with recording off nothing would use them up (recordWaveLog).
			if (config.recordWaveLog())
			{
				waveLog.onNpcAnimation(npc.getIndex(), npc.getAnimation());
			}
		}
		else if (inColosseum && actor != null && actor == client.getLocalPlayer() && config.recordWaveLog())
		{
			waveLog.onPlayerAnimation(actor.getAnimation());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		NPC npc = e.getNpc();
		tracker.onNpcDespawned(npc.getIndex());
		if (inColosseum && npc.getId() == NpcID.COLOSSEUM_MASTER)
		{
			// Minimus leaves once a modifier is picked.
			tracker.onModifierChosen(client.getVarbitValue(VARBIT_MODIFIER_SELECTED));
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired e)
	{
		if (e.getScriptId() != SCRIPT_MODIFIER_SELECT_INIT || e.getScriptEvent() == null)
		{
			return;
		}
		try
		{
			Object[] args = e.getScriptEvent().getArguments();
			tracker.onModifierOptions((Integer) args[2], (Integer) args[3], (Integer) args[4], (Integer) args[8]);
		}
		catch (RuntimeException ex)
		{
			// Never throw into the game's script: a changed script costs the modifiers, not the client.
			log.warn("Could not read the modifier selector's arguments", ex);
		}
	}

	/**
	 * A hitsplat, which RuneLite passes on between ticks: the wave log keeps those on the player and on NPCs for the next
	 * tick it records. Those on the wave's first tick may come before the wave's message, so they are kept whether or not
	 * a wave is being recorded, and dropped on the next tick if none is.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (!inColosseum || !config.recordWaveLog())
		{
			return;
		}
		Actor actor = e.getActor();
		int amount = e.getHitsplat().getAmount();
		int type = e.getHitsplat().getHitsplatType();
		if (actor != null && actor == client.getLocalPlayer())
		{
			waveLog.onPlayerHit(amount, type);
		}
		else if (actor instanceof NPC)
		{
			waveLog.onNpcHit(((NPC) actor).getIndex(), amount, type);
		}
	}

	/**
	 * The game put a graphic on a tile, such as where a Javelin Colossus's special lands: the wave log keeps those on the
	 * grid for the next tick it records, as it does the hitsplats.
	 */
	@Subscribe
	public void onGraphicsObjectCreated(GraphicsObjectCreated e)
	{
		if (!inColosseum || !config.recordWaveLog())
		{
			return;
		}
		GraphicsObject graphic = e.getGraphicsObject();
		waveLog.onTileGraphic(gridTileOf(graphic.getLocation()), graphic.getId());
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		boolean now = isInColosseum();
		if (inColosseum && !now)
		{
			leave();
		}
		inColosseum = now;
		if (!inColosseum)
		{
			return;
		}

		// Every tick, rather than on graphic events, which do not fire for a Manticore out of view behind a pillar.
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.getId() != NpcID.COLOSSEUM_MANTICORE)
			{
				continue;
			}
			for (ActorSpotAnim anim : npc.getSpotAnims())
			{
				OrbStyle style = orbStyleOf(anim.getId());
				if (style != null)
				{
					tracker.onOrb(npc.getIndex(), style);
				}
			}
		}

		int tick = client.getTickCount();
		if (tracker.isWaveStartTick(tick))
		{
			try
			{
				ArenaState start = capture();
				Equipment gear = gear();
				waveStartLink = StatePayload.link(config.siteUrl(), start, gear);
				waveStartState = StatePayload.toJson(start, gear);
			}
			catch (ExportException ex)
			{
				waveStartLink = null;
				waveStartState = null;
			}
		}
		else if (!tracker.isWaveStarted())
		{
			waveStartLink = null;
			waveStartState = null;
		}
		recordWaveLog(tick);
		updatePanel();
	}

	/**
	 * This tick in the wave log: it starts on the first tick of a wave the tracker saw start, records each tick after,
	 * the tick of the game's "Wave N completed!" included, and then stops and keeps the log until the next wave.
	 */
	private void recordWaveLog(int tick)
	{
		if (!config.recordWaveLog())
		{
			// Switched off: no log is kept, not even a half-recorded one.
			if (waveLog.hasLog())
			{
				waveLog.clear();
			}
			waveLog.discardPending();
			return;
		}
		if (tracker.isWaveStartTick(tick) && tracker.getWave() != null)
		{
			waveLog.start(tracker.getWave(), tick, tracker.modifiers(m -> readLevel(m.getLevelVarbit())), tracker.isModifiersComplete(),
				PluginVersion.VERSION, waveStartState);
		}
		if (!waveLog.isRecording())
		{
			waveLog.discardPending();
			return;
		}
		waveLog.record(tick, playerTick(), npcTicks());
		if (!tracker.isWaveStarted())
		{
			waveLog.finish(WaveLog.End.COMPLETED);
		}
	}

	/** The player on this tick, for the wave log, with their gear when "Include gear and stats" is on; on the client thread only. */
	private WaveLog.PlayerTick playerTick()
	{
		Player player = client.getLocalPlayer();
		GridTile tile = player == null ? null : gridTileOf(player.getWorldLocation());
		if (tile != null && !ArenaGeometry.onGrid(tile))
		{
			// Off the grid the log has no tile for the player (WaveLogWriter).
			tile = null;
		}
		int animation = player == null ? -1 : player.getAnimation();
		int target = player == null ? WaveLog.TARGET_NONE : targetOf(player.getInteracting());
		return new WaveLog.PlayerTick(tile, client.getBoostedSkillLevel(Skill.HITPOINTS), client.getBoostedSkillLevel(Skill.PRAYER),
			activePrayers(), animation, target, config.includeGear() ? wornIds() : null);
	}

	/** The item id in each slot the link names, in WaveLog.WORN_SLOTS' order (SLOTS), -1 for an empty one. */
	private int[] wornIds()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item[] items = worn == null ? new Item[0] : worn.getItems();
		int[] ids = new int[SLOTS.length];
		for (int i = 0; i < SLOTS.length; i++)
		{
			int slot = SLOTS[i].getSlotIdx();
			Item item = slot < items.length ? items[slot] : null;
			ids[i] = item == null || item.getId() <= 0 ? -1 : item.getId();
		}
		return ids;
	}

	/**
	 * Every NPC the game shows on this tick, dead ones included, with the graphics it shows, for the wave log, which keeps
	 * those on the grid.
	 */
	private List<WaveLog.NpcTick> npcTicks()
	{
		List<WaveLog.NpcTick> out = new ArrayList<>();
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			GridTile tile = gridTileOf(npc.getWorldLocation());
			if (tile == null)
			{
				continue;
			}
			List<Integer> spots = new ArrayList<>();
			for (ActorSpotAnim anim : npc.getSpotAnims())
			{
				spots.add(anim.getId());
			}
			int[] spotAnims = new int[spots.size()];
			for (int i = 0; i < spotAnims.length; i++)
			{
				spotAnims[i] = spots.get(i);
			}
			out.add(new WaveLog.NpcTick(npc.getIndex(), npc.getId(), tile, npc.getAnimation(), npc.getHealthRatio(), npc.getHealthScale(),
				targetOf(npc.getInteracting()), spotAnims));
		}
		return out;
	}

	/** An actor's target in the wave log: an NPC by its index, any player as the player, since the Colosseum is solo. */
	private static int targetOf(Actor target)
	{
		if (target instanceof NPC)
		{
			return ((NPC) target).getIndex();
		}
		if (target instanceof Player)
		{
			return WaveLog.TARGET_PLAYER;
		}
		return WaveLog.TARGET_NONE;
	}

	/**
	 * The prayers on, by their names in the wave log. Eagle Eye and Deadeye, and Mystic Might and Mystic Vigour, share a
	 * slot in the prayer book, which Client.isPrayerActive does not tell apart; RuneLite's own prayer plugin settles which
	 * one is meant by whether the newer prayer is unlocked, and so does this.
	 */
	@SuppressWarnings("deprecation")
	private List<String> activePrayers()
	{
		boolean deadeye = readLevel(VarbitID.PRAYER_DEADEYE_UNLOCKED) != 0;
		boolean vigour = readLevel(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) != 0;
		List<String> out = new ArrayList<>();
		for (Prayer prayer : Prayer.values())
		{
			if ((prayer == Prayer.EAGLE_EYE && deadeye) || (prayer == Prayer.DEADEYE && !deadeye)
				|| (prayer == Prayer.MYSTIC_MIGHT && vigour) || (prayer == Prayer.MYSTIC_VIGOUR && !vigour))
			{
				continue;
			}
			if (client.isPrayerActive(prayer))
			{
				out.add(WaveLog.prayerName(prayer.name()));
			}
		}
		return out;
	}

	private void leave()
	{
		// The log of a wave the player died in or ran from is kept, so that it can be copied after.
		waveLog.finish(WaveLog.End.LEFT);
		tracker.reset();
		inColosseum = false;
		waveStartLink = null;
		waveStartState = null;
		updatePanel();
	}

	private boolean isInColosseum()
	{
		Player player = client.getLocalPlayer();
		if (player == null || !client.isInInstancedRegion())
		{
			return false;
		}
		LocalPoint lp = player.getLocalLocation();
		return lp != null && WorldPoint.fromLocalInstance(client, lp).getRegionID() == ArenaGeometry.REGION_ID;
	}

	private static OrbStyle orbStyleOf(int spotAnimId)
	{
		switch (spotAnimId)
		{
			case SpotanimID.VFX_MANTICORE_01_PROJECTILE_MAGIC_01:
				return OrbStyle.MAGIC;
			case SpotanimID.VFX_MANTICORE_01_PROJECTILE_RANGED_01:
				return OrbStyle.RANGED;
			case SpotanimID.VFX_MANTICORE_01_PROJECTILE_MELEE_01:
				return OrbStyle.MELEE;
			default:
				return null;
		}
	}

	/** A tile's grid tile, through the instance's template so that it is in region 7216's coordinates. */
	private GridTile gridTileOf(WorldPoint world)
	{
		return gridTileOf(LocalPoint.fromWorld(client.getTopLevelWorldView(), world));
	}

	/** A scene point's grid tile, or null for none, as gridTileOf(WorldPoint). */
	private GridTile gridTileOf(LocalPoint lp)
	{
		if (lp == null)
		{
			return null;
		}
		WorldPoint template = WorldPoint.fromLocalInstance(client, lp);
		if (template.getRegionID() != ArenaGeometry.REGION_ID)
		{
			return null;
		}
		return ArenaGeometry.fromRegion(template.getRegionX(), template.getRegionY());
	}

	/** The arena as it is on this tick; on the client thread only. */
	private ArenaState capture() throws ExportException
	{
		if (!inColosseum)
		{
			throw new ExportException("You are not in the Fortis Colosseum.");
		}
		List<SeenNpc> seen = new ArrayList<>();
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc.isDead())
			{
				continue;
			}
			// An NPC's world location is its south-west tile, the tile the link gives it.
			GridTile tile = gridTileOf(npc.getWorldLocation());
			if (tile != null)
			{
				seen.add(new SeenNpc(npc.getIndex(), npc.getId(), tile));
			}
		}
		Player player = client.getLocalPlayer();
		GridTile playerTile = player == null ? null : gridTileOf(player.getWorldLocation());
		return tracker.capture(client.getTickCount(), playerTile, seen, m -> readLevel(m.getLevelVarbit()));
	}

	/** The skills whose levels go in the link with the gear. */
	private static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC, Skill.HITPOINTS, Skill.PRAYER
	};

	/** The slots the link names: those that hold gear, not the hair and jaw of the player's look. */
	private static final EquipmentInventorySlot[] SLOTS = {
		EquipmentInventorySlot.HEAD, EquipmentInventorySlot.CAPE, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.WEAPON, EquipmentInventorySlot.BODY, EquipmentInventorySlot.SHIELD,
		EquipmentInventorySlot.LEGS, EquipmentInventorySlot.GLOVES, EquipmentInventorySlot.BOOTS,
		EquipmentInventorySlot.RING, EquipmentInventorySlot.AMMO
	};

	/**
	 * The player's gear and stats now, or null when the player has switched them off. The items' names and stats come
	 * from RuneLite's item data; the weapon's category and style are the game's own numbers. On the client thread only.
	 */
	private Equipment gear()
	{
		if (!config.includeGear())
		{
			return null;
		}
		Equipment gear = new Equipment();
		int prayerBonus = 0;
		int weaponSpeed = 0;
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item[] items = worn == null ? new Item[0] : worn.getItems();
		for (EquipmentInventorySlot slot : SLOTS)
		{
			Item item = slot.getSlotIdx() < items.length ? items[slot.getSlotIdx()] : null;
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			String name = itemManager.getItemComposition(item.getId()).getName();
			gear.item(slot.name().toLowerCase(Locale.ROOT), new Equipment.Item(item.getId(), name, item.getQuantity()));
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats != null && stats.getEquipment() != null)
			{
				gear.bonuses(item.getId(), bonusesOf(stats.getEquipment()));
				prayerBonus += stats.getEquipment().getPrayer();
				if (slot == EquipmentInventorySlot.WEAPON)
				{
					weaponSpeed = stats.getEquipment().getAspeed();
				}
			}
		}
		switchesOf(gear);
		int category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		gear.weapon(weaponSpeed, category, client.getVarpValue(VarPlayerID.COM_MODE));
		gear.styleNames(styleNamesOf(category));
		gear.prayer(prayerBonus, client.getBoostedSkillLevel(Skill.PRAYER));
		for (Skill skill : SKILLS)
		{
			gear.stat(skill.name().toLowerCase(Locale.ROOT), client.getBoostedSkillLevel(skill), client.getRealSkillLevel(skill));
		}
		return gear;
	}

	/**
	 * The switches: each item in the inventory that RuneLite's item data says can be worn, with the slot it goes in and a
	 * weapon's attack speed, in the inventory's order. Food, potions and runes have no slot and are left out. On the client thread only.
	 */
	private void switchesOf(Equipment gear)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}
		for (Item item : inventory.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
			{
				continue;
			}
			String slot = slotName(stats.getEquipment().getSlot());
			if (slot == null)
			{
				continue;
			}
			gear.bonuses(item.getId(), bonusesOf(stats.getEquipment()));
			String name = itemManager.getItemComposition(item.getId()).getName();
			int speed = "weapon".equals(slot) ? stats.getEquipment().getAspeed() : 0;
			gear.switchItem(slot, new Equipment.Item(item.getId(), name, item.getQuantity()), speed);
		}
	}

	/** An item's bonuses as the link writes them (Equipment.bonuses), its magic damage in tenths of a percent. */
	private static int[] bonusesOf(ItemEquipmentStats e)
	{
		return new int[]{
			e.getAstab(), e.getAslash(), e.getAcrush(), e.getAmagic(), e.getArange(), e.getStr(), e.getRstr(),
			Math.round(e.getMdmg() * 10), e.isTwoHanded() ? 1 : 0
		};
	}

	/** The link's name of a slot, by its index among the worn items, or null for one it does not name. */
	private static String slotName(int index)
	{
		for (EquipmentInventorySlot slot : SLOTS)
		{
			if (slot.getSlotIdx() == index)
			{
				return slot.name().toLowerCase(Locale.ROOT);
			}
		}
		return null;
	}

	/**
	 * The names of a weapon category's combat options, from the game's data as RuneLite's attack styles plugin reads
	 * them (script 4525's enum and structs); empty when the category has no enum, such as the partisan's.
	 */
	private List<String> styleNamesOf(int category)
	{
		List<String> names = new ArrayList<>();
		try
		{
			int styles = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(category);
			if (styles == -1)
			{
				return names;
			}
			for (int struct : client.getEnum(styles).getIntVals())
			{
				names.add(client.getStructComposition(struct).getStringValue(ParamID.ATTACK_STYLE_NAME));
			}
		}
		catch (RuntimeException ex)
		{
			// The site falls back on the style's place alone.
			log.debug("Could not read the weapon's style names", ex);
			names.clear();
		}
		return names;
	}

	private int readLevel(int varbit)
	{
		try
		{
			return client.getVarbitValue(varbit);
		}
		catch (RuntimeException ex)
		{
			// A varbit the game has moved reads as not taken rather than breaking the export.
			log.debug("Could not read varbit {}", varbit, ex);
			return 0;
		}
	}

	/** Opens the wave start's link on the site, and copies it too, for sharing. */
	private void openWaveStart()
	{
		clientThread.invokeLater(() ->
		{
			if (waveStartLink == null)
			{
				report("No wave start to open: the plugin takes one on the first tick of each wave it sees start.");
				return;
			}
			LinkBrowser.browse(waveStartLink);
			copy(waveStartLink, "Opened the wave start on the site, and copied its link.", "Opened the wave start on the site.");
		});
	}

	/**
	 * Copies the arena's link of now: the hotkey only copies, and the panel's button (`open`) opens it on the site too, as
	 * opening a browser from a key pressed in the game would take the player out of it.
	 */
	private void copyCurrent(boolean open)
	{
		clientThread.invokeLater(() ->
		{
			try
			{
				ArenaState state = capture();
				String done = open ? "Opened the arena on the site, and copied its link." : "Copied the arena's link.";
				String note = state.isModifiersComplete()
					? done
					: done + " Quartet, Red Flag and Totemic show from your next modifier pick on: set them on the site.";
				String link = StatePayload.link(config.siteUrl(), state, gear());
				if (open)
				{
					LinkBrowser.browse(link);
				}
				copy(link, note, open ? "Opened the arena on the site." : null);
			}
			catch (ExportException ex)
			{
				report(ex.getMessage());
			}
		});
	}

	/**
	 * Opens the site's modifier pick in the browser with the three modifiers Minimus offers filled in, while his selector
	 * is open: the link holds them, the modifiers held and the next wave, and nothing else.
	 */
	private void openRecommender()
	{
		clientThread.invokeLater(() ->
		{
			List<Modifier> offers = tracker.getOptions();
			if (offers.isEmpty())
			{
				report("No offers to open: press this while Minimus offers his three modifiers.");
				return;
			}
			Integer wave = tracker.getWave();
			String link = PickPayload.link(config.siteUrl(), wave, tracker.modifiers(m -> readLevel(m.getLevelVarbit())), offers);
			LinkBrowser.browse(link);
			report(wave == null
				? "Opened the recommender with Minimus's offers. The plugin has not seen a wave yet: set the wave on the site."
				: "Opened the recommender with Minimus's offers for wave " + wave + ".");
		});
	}

	/** Copies the log the panel's list picked, by its id: the wave under way or the last one, or a past one. */
	private void copyWaveLog(int id)
	{
		clientThread.invokeLater(() ->
		{
			if (!waveLog.hasLog())
			{
				report(config.recordWaveLog()
					? "No wave log to copy: the plugin records each wave it sees start."
					: "No wave log to copy: switch on \"Record wave log\" in the plugin's settings.");
				return;
			}
			if (waveLog.getId() == id)
			{
				String note = "Copied the wave log of wave " + waveLog.getWave() + ", " + waveLog.size() + " ticks"
					+ (waveLog.isCut() ? ", cut at " + WaveLog.MAX_TICKS : "") + ".";
				copy(WaveLogWriter.toJson(waveLog), note, null);
				return;
			}
			for (WaveLog.Past past : waveLog.getPast())
			{
				if (past.getId() == id)
				{
					copy(past.getJson(), "Copied the wave log of wave " + past.getWave() + ", " + past.size() + " ticks.", null);
					return;
				}
			}
			// Kept no longer: more waves have come since than the log keeps.
			report("That wave log is no longer kept: pick another.");
		});
	}

	/**
	 * Copies every wave of the newest run in one paste, whichever wave the list picked: the logs WaveLog.getRun picks, as
	 * RunLogWriter writes them.
	 */
	private void copyRun()
	{
		clientThread.invokeLater(() ->
		{
			List<WaveLog.Past> run = waveLog.getRun();
			if (run.isEmpty())
			{
				report(config.recordWaveLog()
					? "No wave log to copy: the plugin records each wave it sees start."
					: "No wave log to copy: switch on \"Record wave log\" in the plugin's settings.");
				return;
			}
			int from = run.get(0).getWave();
			int to = run.get(run.size() - 1).getWave();
			int ticks = 0;
			for (WaveLog.Past wave : run)
			{
				ticks += wave.size();
			}
			String waves = from == to ? "wave " + from : "waves " + from + " to " + to;
			String note = "Copied the whole run, " + waves + ", " + ticks + (ticks == 1 ? " tick" : " ticks") + "."
				+ (from == 1 ? "" : " The plugin logged it from wave " + from + " on.");
			copy(RunLogWriter.toJson(run, PluginVersion.VERSION), note, null);
		});
	}

	/**
	 * Puts `text` on the clipboard and says `message`. Another program may hold the clipboard, as on Windows, and then
	 * the player hears so, after `opened` when the link opened anyway.
	 */
	private void copy(String text, String message, String opened)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
		}
		catch (IllegalStateException ex)
		{
			log.debug("Could not copy to the clipboard", ex);
			String busy = "Another program is using the clipboard, so nothing was copied: try again.";
			report(opened == null ? busy : opened + " " + busy);
			return;
		}
		report(message);
	}

	/** Tells the player what happened, in the panel and, if they want it, in the chat box. */
	private void report(String message)
	{
		if (config.chatConfirm())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage("[Sol Survivor] " + message)
				.build());
		}
		SolSurvivorPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.showResult(message));
		}
	}

	private void updatePanel()
	{
		SolSurvivorPanel p = panel;
		if (p == null)
		{
			return;
		}
		boolean colosseum = inColosseum;
		boolean waveStart = waveStartLink != null;
		String log = waveLogStatus();
		List<SolSurvivorPanel.LogChoice> logs = logChoices();
		boolean offers = !tracker.getOptions().isEmpty();
		if (colosseum == shownInColosseum && waveStart == shownWaveStart && log.equals(shownWaveLog) && logs.equals(shownLogs)
			&& offers == shownOffers)
		{
			return;
		}
		shownInColosseum = colosseum;
		shownWaveStart = waveStart;
		shownWaveLog = log;
		shownLogs = logs;
		shownOffers = offers;
		SwingUtilities.invokeLater(() -> p.showState(colosseum, waveStart, offers, log, logs));
	}

	/**
	 * The logs the panel's list offers, newest first: the wave under way or the last one, then the past ones. A wave under
	 * way leaves its tick count out, so that the list stays as it is, and keeps the player's pick, while it records.
	 */
	private List<SolSurvivorPanel.LogChoice> logChoices()
	{
		List<SolSurvivorPanel.LogChoice> out = new ArrayList<>();
		if (!waveLog.hasLog())
		{
			return out;
		}
		String now = waveLog.isRecording() ? "recording" : waveLog.size() + " ticks, " + endName(waveLog.getEnd());
		out.add(new SolSurvivorPanel.LogChoice(waveLog.getId(), "Wave " + waveLog.getWave() + ", " + now));
		for (WaveLog.Past past : waveLog.getPast())
		{
			out.add(new SolSurvivorPanel.LogChoice(past.getId(), "Wave " + past.getWave() + ", " + past.size() + " ticks, " + endName(past.getEnd())));
		}
		return out;
	}

	/** How a log's wave ended, in the panel's words. */
	private static String endName(WaveLog.End end)
	{
		if (end == null)
		{
			return "end not seen";
		}
		return end == WaveLog.End.COMPLETED ? "completed" : "left";
	}

	/** What the panel says of the wave log: which wave, how many ticks, and whether it is still recording. */
	private String waveLogStatus()
	{
		if (!config.recordWaveLog())
		{
			return "Wave log: off.";
		}
		if (!waveLog.hasLog())
		{
			return "Wave log: none yet. It records each wave the plugin sees start.";
		}
		String state;
		if (waveLog.isRecording())
		{
			state = waveLog.isCut() ? "full, the rest is left out" : "recording";
		}
		else
		{
			state = waveLog.getEnd() == WaveLog.End.COMPLETED ? "wave completed" : "left the wave";
		}
		int past = waveLog.getPast().size();
		return "Wave log: wave " + waveLog.getWave() + ", " + waveLog.size() + (waveLog.size() == 1 ? " tick" : " ticks") + " (" + state + ")."
			+ (past == 0 ? "" : " The list also holds " + (past == 1 ? "the wave" : "the " + past + " waves") + " before it.");
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * The Colosseum's arena and the transform from the game's region coordinates to the LoS tool's grid (combat research §9):
 * x = regionX - 16 and y = 51 - regionY, in region 7216. The game gives an instance's tiles in their template's region,
 * which the RuneLite layer reads with WorldPoint.fromLocalInstance.
 */
public final class ArenaGeometry
{
	/** The arena's region, the template the instance is copied from. */
	public static final int REGION_ID = 7216;

	/** The lobby's region, where the run is entered from. */
	public static final int LOBBY_REGION_ID = 7316;

	/** The grid's width and height in tiles: 0 to 33 each way, the state link's MAP_SIZE. */
	public static final int SIZE = 34;

	private ArenaGeometry()
	{
	}

	/** The grid tile of a tile in the region, by its coordinates within it (0 to 63 each). */
	public static GridTile fromRegion(int regionX, int regionY)
	{
		return new GridTile(regionX - 16, 51 - regionY);
	}

	/** Whether a grid tile is on the grid the state link takes. */
	public static boolean onGrid(GridTile tile)
	{
		return tile.getX() >= 0 && tile.getX() < SIZE && tile.getY() >= 0 && tile.getY() < SIZE;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The arena on one tick, as the state link's `setup` holds it (src/link/statePayload.ts, SetupV1). A field the plugin
 * does not know is null, and the link leaves it out, so that the site falls back on its own: the wave when the plugin
 * started after the wave's message, the tick within the wave likewise.
 */
public final class ArenaState
{
	private final List<ExportNpc> npcs;
	private final GridTile player;
	private final boolean waveStart;
	private final Integer wave;
	private final Integer waveTick;
	private final boolean reinforcementsArrived;
	private final Map<Modifier, Integer> modifiers;
	private final boolean modifiersComplete;
	private final List<GridTile> solarflareOrbs;

	public ArenaState(
		List<ExportNpc> npcs,
		GridTile player,
		boolean waveStart,
		Integer wave,
		Integer waveTick,
		boolean reinforcementsArrived,
		Map<Modifier, Integer> modifiers,
		boolean modifiersComplete,
		List<GridTile> solarflareOrbs)
	{
		this.npcs = Collections.unmodifiableList(npcs);
		this.player = player;
		this.waveStart = waveStart;
		this.wave = wave;
		this.waveTick = waveTick;
		this.reinforcementsArrived = reinforcementsArrived;
		this.modifiers = Collections.unmodifiableMap(modifiers);
		this.modifiersComplete = modifiersComplete;
		this.solarflareOrbs = Collections.unmodifiableList(solarflareOrbs);
	}

	/** The tiles of Solarflare's orbs on this tick, in the order the game lists them; empty without Solarflare. */
	public List<GridTile> getSolarflareOrbs()
	{
		return solarflareOrbs;
	}

	public List<ExportNpc> getNpcs()
	{
		return npcs;
	}

	public GridTile getPlayer()
	{
		return player;
	}

	/** Whether this is the wave's first tick, the LoS link's "_ws". */
	public boolean isWaveStart()
	{
		return waveStart;
	}

	/** The wave, 1 to 11, or null when the plugin has not seen it start. */
	public Integer getWave()
	{
		return wave;
	}

	/** Mid-wave: how many ticks ago the wave started, or null when the plugin has not seen it start. */
	public Integer getWaveTick()
	{
		return waveTick;
	}

	/** Mid-wave: whether the wave's reinforcements have come, after which none will. */
	public boolean isReinforcementsArrived()
	{
		return reinforcementsArrived;
	}

	/** The modifiers taken, each with its tier (1 for one without tiers). */
	public Map<Modifier, Integer> getModifiers()
	{
		return modifiers;
	}

	/**
	 * Whether the modifiers are all known. Those with tiers are read from their varbits at any time; Quartet, Red Flag and
	 * Totemic only from the modifier selector, so a plugin started mid-run knows them from the next pick on.
	 */
	public boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	/** Mantimayhem III, the LoS link's "_mm3", which lets a Manticore fire its melee orb first. */
	public boolean isMm3()
	{
		Integer level = modifiers.get(Modifier.MANTIMAYHEM);
		return level != null && level == 3;
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * The animations that mark a Colosseum NPC's attack, so that the plugin can time each NPC's next attack and count a
 * Javelin Colossus's throws (the design spec's "Attack timing"). Partly confirmed: the ids are taken from the names RuneLite
 * gives the game's animations (net.runelite.api.gameval.AnimationID), and the user's wave logs have confirmed four of them so far.
 *
 * - The first wave log (wave 2, 2026-10-18) showed the shaman casting with SHAMAN_CAST while its spells hit the player,
 *   and the Javelin Colossus with JAVELIN_THROW as its javelin hit. The second (wave 2 again) had both attack 5 ticks
 *   apart, as the site's engine has them.
 * - The third (wave 1, 2026-10-18), the first with the animation starts, showed the Jaguar warrior starting JAGUAR_CLAWS
 *   every 5 ticks from the tick after it reached a tile beside the player, each attack bringing three hitsplats on the
 *   player. The shaman started SHAMAN_CAST every 5 ticks too, and 10860 when it died.
 * - The fourth (wave 2, Reentry I and Frailty I) showed a Javelin Colossus throwing JAVELIN_THROW four times and then
 *   JAVELIN_SPECIAL as its 5th, 10th and 15th attacks, 5 ticks apart throughout. It first attacked 833 ticks after it
 *   spawned, so the special is counted by its attacks, as ColosseumTracker counts them, not by ticks since its spawn.
 *   The Jaguar there started 10848 (its block) each time the player hit it, which is not an attack.
 * - Still unconfirmed: the Minotaur's two and SHOCKWAVE_CLAP.
 *
 * The logs also showed each NPC's death: the shaman 10860, the Jaguar 10849 and the Javelin Colossus 10894.
 *
 * Each NPC shows 10861 on the wave's first ticks, its spawn, and a Jaguar that spawns mid-wave shows 10862.
 *
 * The Manticore is left out: its attacks are its orbs, which OrbOrder follows, and its timer turns on its charge. So is
 * the Minotaur's heal, which shares its attack timer but has no animation named for it.
 */
public final class AttackAnimations
{
	/** NPC_SERPENT_MAGER_CASTING: the serpent shaman's spell. */
	public static final int SHAMAN_CAST = 10859;
	/** NPC_COLOSSI_JAVELIN_01_RANGE_ATTACK: the Javelin Colossus's normal throw. */
	public static final int JAVELIN_THROW = 10892;
	/** NPC_COLOSSI_JAVELIN_01_ARTILLERY_ATTACK: the Javelin Colossus's special, the javelins that land on tiles. */
	public static final int JAVELIN_SPECIAL = 10893;
	/** NPC_JAGUAR_RANGER_CLAWS_ATTACK: the Jaguar warrior's claws. */
	public static final int JAGUAR_CLAWS = 10847;
	/** NPC_MINOTAUR_BOSS_ATTACK_MELEE: the Minotaur's melee attack. */
	public static final int MINOTAUR_MELEE = 10843;
	/** NPC_MINOTAUR_BOSS_ATTACK_MAGIC: the Minotaur's other attack animation, counted as an attack too. */
	public static final int MINOTAUR_MAGIC = 10844;
	/** NPC_COLOSSI_SHOCKWAVE_01_CLAPATTACK: the Shockwave Colossus's clap. */
	public static final int SHOCKWAVE_CLAP = 10903;

	private AttackAnimations()
	{
	}

	/** Whether an animation of an NPC of this id is one of its attacks. */
	public static boolean isAttack(int npcId, int animationId)
	{
		switch (npcId)
		{
			case NpcKind.SHAMAN_ID:
				return animationId == SHAMAN_CAST;
			case NpcKind.JAVELIN_ID:
				return animationId == JAVELIN_THROW || animationId == JAVELIN_SPECIAL;
			case NpcKind.JAGUAR_ID:
				return animationId == JAGUAR_CLAWS;
			case NpcKind.MINOTAUR_ID:
			case NpcKind.MINOTAUR_RED_FLAG_ID:
				return animationId == MINOTAUR_MELEE || animationId == MINOTAUR_MAGIC;
			case NpcKind.SHOCKWAVE_ID:
				return animationId == SHOCKWAVE_CLAP;
			default:
				return false;
		}
	}

	/** Whether an animation of an NPC of this id is a Javelin Colossus's special. */
	public static boolean isSpecial(int npcId, int animationId)
	{
		return npcId == NpcKind.JAVELIN_ID && animationId == JAVELIN_SPECIAL;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the plugin remembers of a Colosseum run between ticks, fed the game's events by the RuneLite layer and free of
 * RuneLite itself, so that its tests run on mocked game data. It follows the wave from the game's chat messages, which
 * NPCs spawned after the wave's first tick (the reinforcements), the orbs each Manticore has shown, each NPC's attacks,
 * and the modifiers taken; capture() turns that and the NPCs and player of a tick into an ArenaState.
 *
 * It only reads: nothing here, or in the plugin, acts on the game or draws in it.
 */
public final class ColosseumTracker
{
	/** The last wave Sol Survivor plans: wave 12 is Sol Heredit. */
	public static final int LAST_WAVE = 11;

	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern WAVE_START = Pattern.compile("Wave: (\\d+)");
	private static final Pattern WAVE_DONE = Pattern.compile("Wave (\\d+) completed!");
	private static final String SOL_START = "Sol Heredit jumps down from his seat";

	private Integer wave;
	private boolean waveStarted;
	private int waveStartTick = -1;

	/** The NPCs, by index, that spawned after their wave's first tick. */
	private final Set<Integer> reinforcements = new HashSet<>();
	/** Whether a reinforcement has come this wave, even one that has since died. */
	private boolean reinforcementsArrived;
	private final Map<Integer, OrbOrder> orbs = new HashMap<>();
	/** The tick each NPC's last attack animation started on, by index. */
	private final Map<Integer, Integer> lastAttack = new HashMap<>();
	/**
	 * The attacks each NPC has made, by index, for those whose count is known: it spawned while the plugin watched, or for
	 * a Javelin Colossus the plugin saw a special. Kept across the wave's start, since the game may spawn the wave's NPCs
	 * before or after its message on the same tick; an NPC's despawn clears its entries.
	 */
	private final Map<Integer, Integer> attackCounts = new HashMap<>();

	private final Set<Modifier> taken = EnumSet.noneOf(Modifier.class);
	private boolean modifiersComplete;
	private final List<Modifier> options = new ArrayList<>(3);

	/** Forget the run: the player left the Colosseum, hopped or logged out. */
	public void reset()
	{
		wave = null;
		waveStarted = false;
		waveStartTick = -1;
		taken.clear();
		modifiersComplete = false;
		options.clear();
		lastAttack.clear();
		attackCounts.clear();
		resetWave();
	}

	private void resetWave()
	{
		reinforcements.clear();
		reinforcementsArrived = false;
		orbs.clear();
	}

	/** A game message, on the tick it came. */
	public void onGameMessage(String message, int tick)
	{
		String text = TAG.matcher(message).replaceAll("");
		Matcher m;
		if (text.contains(SOL_START))
		{
			startWave(LAST_WAVE + 1, tick);
		}
		else if ((m = WAVE_START.matcher(text)).find())
		{
			startWave(Integer.parseInt(m.group(1)), tick);
		}
		else if ((m = WAVE_DONE.matcher(text)).find())
		{
			wave = Integer.parseInt(m.group(1)) + 1;
			waveStarted = false;
			resetWave();
		}
	}

	private void startWave(int number, int tick)
	{
		wave = number;
		waveStarted = true;
		waveStartTick = tick;
		resetWave();
	}

	/** Whether this tick is the first of a wave the plugin saw start. */
	public boolean isWaveStartTick(int tick)
	{
		return waveStarted && tick == waveStartTick;
	}

	/** Whether a wave is under way that the plugin saw start. */
	public boolean isWaveStarted()
	{
		return waveStarted;
	}

	/** The wave under way, or the next one between waves; null when the plugin has not seen a wave's message yet. */
	public Integer getWave()
	{
		return wave;
	}

	/** Whether the modifiers taken are all known: see ArenaState.isModifiersComplete. */
	public boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	/** An NPC spawned, on the tick it did. One that spawns after its wave's first tick is a reinforcement. */
	public void onNpcSpawned(int index, int npcId, int tick)
	{
		if (NpcKind.forNpcId(npcId, false) == null)
		{
			return;
		}
		if (waveStarted && tick != waveStartTick)
		{
			reinforcements.add(index);
			reinforcementsArrived = true;
		}
		if (npcId == NpcKind.MANTICORE_ID)
		{
			orbs.put(index, new OrbOrder());
		}
		else
		{
			lastAttack.remove(index);
			attackCounts.put(index, 0);
		}
	}

	public void onNpcDespawned(int index)
	{
		reinforcements.remove(index);
		orbs.remove(index);
		lastAttack.remove(index);
		attackCounts.remove(index);
	}

	/**
	 * An NPC started an animation, on the tick it did. An attack (AttackAnimations, unconfirmed) restarts its attack timer
	 * and adds to its count. A Javelin Colossus's special is its 5th attack (JAVELIN_SPECIAL_EVERY on the site), so it
	 * sets the count to the next multiple of 5, which fixes the phase of its specials even when the plugin missed its
	 * spawn.
	 */
	public void onNpcAnimation(int index, int npcId, int animationId, int tick)
	{
		if (!AttackAnimations.isAttack(npcId, animationId))
		{
			return;
		}
		lastAttack.put(index, tick);
		Integer count = attackCounts.get(index);
		if (AttackAnimations.isSpecial(npcId, animationId))
		{
			int next = count == null ? 1 : count + 1;
			attackCounts.put(index, (next + 4) / 5 * 5);
		}
		else if (count != null)
		{
			attackCounts.put(index, count + 1);
		}
	}

	/** An orb graphic on a Manticore this tick. */
	public void onOrb(int index, OrbStyle style)
	{
		orbs.computeIfAbsent(index, i -> new OrbOrder()).see(style);
	}

	/**
	 * The modifier selector opened between waves: the game ids of the three on offer, and the mask of those already taken,
	 * which settles every modifier taken so far.
	 */
	public void onModifierOptions(int first, int second, int third, int takenMask)
	{
		options.clear();
		options.add(Modifier.forId(first));
		options.add(Modifier.forId(second));
		options.add(Modifier.forId(third));
		taken.addAll(Modifier.forMask(takenMask));
		modifiersComplete = true;
	}

	/**
	 * The three modifiers the selector offers while it is open, in its order, each null for an id this plugin does not
	 * know; empty while it is closed.
	 */
	public List<Modifier> getOptions()
	{
		return Collections.unmodifiableList(new ArrayList<>(options));
	}

	/** The selector closed with the option at `choice`, 1 to 3; 0 when none was picked. */
	public void onModifierChosen(int choice)
	{
		if (choice >= 1 && choice <= options.size() && options.get(choice - 1) != null)
		{
			taken.add(options.get(choice - 1));
		}
		options.clear();
	}

	/**
	 * The arena on this tick: the NPCs the game shows, the player's tile and the modifiers' tiers, with what the tracker
	 * remembers. An ExportException says why there is nothing to export, such as no NPCs or Sol Heredit's wave.
	 */
	public ArenaState capture(int tick, GridTile player, List<SeenNpc> seen, ModifierLevels levels) throws ExportException
	{
		if (wave != null && wave > LAST_WAVE)
		{
			throw new ExportException("Sol Survivor plans waves 1 to 11, not Sol Heredit's.");
		}
		if (player == null || !ArenaGeometry.onGrid(player))
		{
			throw new ExportException("You are not in the Colosseum's arena.");
		}

		Map<Modifier, Integer> modifiers = modifiers(levels);
		boolean mm3 = Integer.valueOf(3).equals(modifiers.get(Modifier.MANTIMAYHEM));
		boolean waveStart = isWaveStartTick(tick);

		List<ExportNpc> npcs = new ArrayList<>();
		List<GridTile> solarflareOrbs = new ArrayList<>();
		boolean arrived = reinforcementsArrived;
		for (SeenNpc n : seen)
		{
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID && ArenaGeometry.onGrid(n.getTile()))
			{
				solarflareOrbs.add(n.getTile());
				continue;
			}
			NpcKind kind = NpcKind.forNpcId(n.getNpcId(), isReinforcement(n));
			if (kind == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			// The Jaguar, the Minotaur and the second shaman only ever come as reinforcements.
			arrived |= kind == NpcKind.JAGUAR_WARRIOR || kind == NpcKind.MINOTAUR || kind == NpcKind.REINFORCEMENT_SHAMAN;
			String code = null;
			Integer sinceAttack = null;
			Integer attacks = null;
			if (kind == NpcKind.MANTICORE)
			{
				OrbOrder order = orbs.get(n.getIndex());
				code = order == null ? "u" : order.losCode(mm3);
			}
			else if (!waveStart)
			{
				Integer last = lastAttack.get(n.getIndex());
				sinceAttack = last == null ? null : Integer.valueOf(tick - last);
				attacks = attackCounts.get(n.getIndex());
			}
			npcs.add(new ExportNpc(kind, n.getTile(), code, sinceAttack, attacks));
		}
		if (npcs.isEmpty())
		{
			throw new ExportException("There are no NPCs in the arena to export.");
		}

		Integer waveTick = waveStarted && !waveStart ? Integer.valueOf(tick - waveStartTick) : null;
		return new ArenaState(npcs, player, waveStart, waveStarted ? wave : null, waveTick, !waveStart && arrived, modifiers, modifiersComplete,
			solarflareOrbs);
	}

	/**
	 * Whether an NPC came as a reinforcement: it spawned after its wave's first tick. A shaman already there when the
	 * plugin started is the reinforcement one from wave 7 on, where no wave starts with a shaman; before, it is taken for
	 * the wave's own.
	 */
	private boolean isReinforcement(SeenNpc n)
	{
		if (reinforcements.contains(n.getIndex()))
		{
			return true;
		}
		return n.getNpcId() == NpcKind.SHAMAN_ID && wave != null && wave >= 7;
	}

	/** The modifiers taken, with their tiers: those with tiers by their varbits. The wave log names them too. */
	public Map<Modifier, Integer> modifiers(ModifierLevels levels)
	{
		Map<Modifier, Integer> out = new EnumMap<>(Modifier.class);
		for (Modifier m : Modifier.values())
		{
			if (m.hasTiers())
			{
				int level = Math.max(0, Math.min(3, levels.level(m)));
				// A modifier the selector says is taken is at tier I at least, whatever its varbit reads.
				if (level == 0 && taken.contains(m))
				{
					level = 1;
				}
				if (level > 0)
				{
					out.put(m, level);
				}
			}
			else if (taken.contains(m))
			{
				out.put(m, 1);
			}
		}
		return out;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The player's gear and stats as the game shows them (design spec, "Equipment"): each worn item by its slot, with its id,
 * name and quantity; the weapon's attack speed in ticks, its category and the attack style picked, as the game numbers
 * them; the items in the inventory that can be worn, the switches a player brings; each item's attack and strength bonuses; the gear's prayer bonus; the prayer points now; and each combat skill's boosted and real level. The site maps
 * them to its kill table; the plugin passes on what the game says and works nothing out.
 */
public final class Equipment
{
	/** A worn item. */
	public static final class Item
	{
		private final int id;
		private final String name;
		private final int quantity;

		public Item(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}

		public int getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}

	/** An item in the inventory that can be worn, the slot it goes in, and a weapon's attack speed in ticks (0 unknown). */
	public static final class Switch
	{
		private final String slot;
		private final Item item;
		private final int speed;

		public Switch(String slot, Item item, int speed)
		{
			this.slot = slot;
			this.item = item;
			this.speed = speed;
		}

		public int getSpeed()
		{
			return speed;
		}

		public String getSlot()
		{
			return slot;
		}

		public Item getItem()
		{
			return item;
		}
	}

	/** The numbers an item's bonuses hold (bonuses). */
	public static final int BONUS_COUNT = 9;

	/** The most switches kept: the inventory's 28 places. */
	public static final int MAX_SWITCHES = 28;

	private final Map<String, Item> items = new LinkedHashMap<>();
	private final List<Switch> switches = new ArrayList<>();
	private final Map<String, int[]> stats = new LinkedHashMap<>();
	private final Map<Integer, int[]> bonuses = new LinkedHashMap<>();
	private int weaponSpeed;
	private int weaponCategory;
	private int attackStyle;
	private final List<String> styleNames = new ArrayList<>();
	private int prayerBonus;
	private int prayerPoints;

	/** An item worn in a slot, by the slot's name in lower case, such as "weapon" or "ammo". */
	public Equipment item(String slot, Item item)
	{
		items.put(slot, item);
		return this;
	}

	/**
	 * An item in the inventory that can be worn, by the slot it goes in, in the inventory's order; past MAX_SWITCHES it is
	 * passed over.
	 */
	public Equipment switchItem(String slot, Item item)
	{
		return switchItem(slot, item, 0);
	}

	/** A weapon in the inventory, with its attack speed in ticks (0 unknown). */
	public Equipment switchItem(String slot, Item item, int speed)
	{
		if (switches.size() < MAX_SWITCHES)
		{
			switches.add(new Switch(slot, item, speed));
		}
		return this;
	}

	/**
	 * An item's bonuses, by its id: stab, slash, crush, magic and ranged attack, melee and ranged strength, magic damage
	 * in tenths of a percent, and 1 when it takes both hands, else 0. The site works out kill times from them.
	 */
	public Equipment bonuses(int id, int[] values)
	{
		if (values.length != BONUS_COUNT)
		{
			throw new IllegalArgumentException("expected " + BONUS_COUNT + " bonuses, not " + values.length);
		}
		bonuses.put(id, values.clone());
		return this;
	}

	/** A skill's boosted and real level, by the skill's name in lower case, such as "ranged". */
	public Equipment stat(String skill, int boosted, int real)
	{
		stats.put(skill, new int[]{boosted, real});
		return this;
	}

	/** The weapon's attack speed in ticks (0 when unknown), its category varbit and the attack style varp. */
	public Equipment weapon(int speed, int category, int style)
	{
		this.weaponSpeed = speed;
		this.weaponCategory = category;
		this.attackStyle = style;
		return this;
	}

	/**
	 * The names the game's data gives the weapon's combat options, in attackStyle's order ("Ranging", "Longrange", and
	 * "Other" for an empty place), which tell the site which style is picked.
	 */
	public Equipment styleNames(List<String> names)
	{
		styleNames.clear();
		styleNames.addAll(names);
		return this;
	}

	/** The gear's prayer bonus, summed over the worn items, and the prayer points now. */
	public Equipment prayer(int bonus, int points)
	{
		this.prayerBonus = bonus;
		this.prayerPoints = points;
		return this;
	}

	public Map<String, Item> getItems()
	{
		return Collections.unmodifiableMap(items);
	}

	public List<Switch> getSwitches()
	{
		return Collections.unmodifiableList(switches);
	}

	public Map<Integer, int[]> getBonuses()
	{
		return Collections.unmodifiableMap(bonuses);
	}

	public Map<String, int[]> getStats()
	{
		return Collections.unmodifiableMap(stats);
	}

	public int getWeaponSpeed()
	{
		return weaponSpeed;
	}

	public int getWeaponCategory()
	{
		return weaponCategory;
	}

	public int getAttackStyle()
	{
		return attackStyle;
	}

	public List<String> getStyleNames()
	{
		return Collections.unmodifiableList(styleNames);
	}

	public int getPrayerBonus()
	{
		return prayerBonus;
	}

	public int getPrayerPoints()
	{
		return prayerPoints;
	}
}

package nl.dexanddice.solsurvivor.core;

/** Why the arena cannot be exported now: the message says so in words the player can act on. */
public class ExportException extends Exception
{
	public ExportException(String message)
	{
		super(message);
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * An NPC as the state link holds it: its kind, its south-west tile and, for a Manticore, its orb code; and what the plugin
 * saw of its attacks, for the link's `attacks`.
 */
public final class ExportNpc
{
	private final NpcKind kind;
	private final GridTile tile;
	private final String orbs;
	private final Integer sinceAttack;
	private final Integer attacks;

	public ExportNpc(NpcKind kind, GridTile tile, String orbs)
	{
		this(kind, tile, orbs, null, null);
	}

	public ExportNpc(NpcKind kind, GridTile tile, String orbs, Integer sinceAttack, Integer attacks)
	{
		this.kind = kind;
		this.tile = tile;
		this.orbs = orbs;
		this.sinceAttack = sinceAttack;
		this.attacks = attacks;
	}

	/** How many ticks ago its last attack animation started, or null when the plugin has seen none. */
	public Integer getSinceAttack()
	{
		return sinceAttack;
	}

	/**
	 * The attacks it has made, or null when the plugin does not know: it saw the NPC spawn and counted each one since, or
	 * for a Javelin Colossus it saw a special, which sets the count to a multiple of 5.
	 */
	public Integer getAttacks()
	{
		return attacks;
	}

	public NpcKind getKind()
	{
		return kind;
	}

	public GridTile getTile()
	{
		return tile;
	}

	/** The Manticore's LoS link orb code, or null for any other NPC. */
	public String getOrbs()
	{
		return orbs;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Objects;

/**
 * A tile of the arena in the LoS tool's terms, as Sol Survivor's state link holds it: x runs east and y south, each from
 * 0 to 33.
 */
public final class GridTile
{
	private final int x;
	private final int y;

	public GridTile(int x, int y)
	{
		this.x = x;
		this.y = y;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof GridTile))
		{
			return false;
		}
		GridTile t = (GridTile) o;
		return x == t.x && y == t.y;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(x, y);
	}

	@Override
	public String toString()
	{
		return "(" + x + "," + y + ")";
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.EnumSet;
import java.util.Set;

/**
 * The Colosseum's modifiers: the game's id for each (its bit in the taken-modifiers mask the selector script gets), the
 * varbit that holds its tier where it has tiers, and its key in the state link's `modifiers` (SimConfig's names). The ids
 * and varbits are the ones the Fortis Colosseum plugin reads (LlemonDuck, BSD 2-Clause). Bees! and Dynamic Duo are
 * exported as "bees" and "dynamicDuo" so that the link names every modifier taken; the site does not simulate them, and
 * its reader passes over names it does not know.
 */
public enum Modifier
{
	MANTIMAYHEM(0, 4588, "mantimayhem"),
	REENTRY(1, 9792, "reentry"),
	BEES(2, 9791, "bees"),
	VOLATILITY(3, 9799, "volatility"),
	BLASPHEMY(4, 9790, "blasphemy"),
	RELENTLESS(5, 9798, "relentless"),
	QUARTET(6, -1, "quartet"),
	TOTEMIC(7, -1, "totemic"),
	DOOM(8, 10681, "doom"),
	DYNAMIC_DUO(9, -1, "dynamicDuo"),
	SOLARFLARE(10, 9797, "solarflare"),
	MYOPIA(11, 9795, "myopia"),
	FRAILTY(12, 9796, "frailty"),
	RED_FLAG(13, -1, "redFlag");

	/** The level varbit of a modifier without tiers (written -1 above, where a constant cannot yet be named). */
	private static final int NO_TIERS = -1;

	private final int id;
	private final int levelVarbit;
	private final String key;

	Modifier(int id, int levelVarbit, String key)
	{
		this.id = id;
		this.levelVarbit = levelVarbit;
		this.key = key;
	}

	/** The game's id, which is also its bit in the taken-modifiers mask. */
	public int getId()
	{
		return id;
	}

	/** Whether it has tiers I to III, whose level a varbit holds. */
	public boolean hasTiers()
	{
		return levelVarbit != NO_TIERS;
	}

	/** The varbit that holds its tier, 0 while it is not taken; only for a modifier with tiers. */
	public int getLevelVarbit()
	{
		return levelVarbit;
	}

	/** Its key in the state link's `modifiers`. */
	public String getKey()
	{
		return key;
	}

	/** The modifier with a game id, or null for an id this plugin does not know. */
	public static Modifier forId(int id)
	{
		for (Modifier m : values())
		{
			if (m.id == id)
			{
				return m;
			}
		}
		return null;
	}

	/** The modifiers in a taken-modifiers mask. */
	public static Set<Modifier> forMask(int mask)
	{
		Set<Modifier> out = EnumSet.noneOf(Modifier.class);
		for (Modifier m : values())
		{
			if ((mask & (1 << m.id)) != 0)
			{
				out.add(m);
			}
		}
		return out;
	}
}

