package nl.dexanddice.solsurvivor.core;

/**
 * The Colosseum's NPCs that a state link holds, with the game's NPC ids (combat research §1) and the LoS link's type codes
 * (src/data/types.ts). The Fremennik warband has no code: links never hold frems. A serpent shaman that spawns after the
 * wave's first tick is the reinforcement shaman, which the link codes apart.
 */
public enum NpcKind
{
	SERPENT_SHAMAN(1),
	JAVELIN_COLOSSUS(2),
	JAGUAR_WARRIOR(3),
	MANTICORE(4),
	MINOTAUR(5),
	SHOCKWAVE_COLOSSUS(6),
	REINFORCEMENT_SHAMAN(7);

	public static final int SHAMAN_ID = 12811;
	public static final int JAGUAR_ID = 12810;
	public static final int MINOTAUR_ID = 12812;
	/** The Minotaur under Red Flag, which routefinds round the pillars. */
	public static final int MINOTAUR_RED_FLAG_ID = 12813;
	public static final int JAVELIN_ID = 12817;
	public static final int MANTICORE_ID = 12818;
	public static final int SHOCKWAVE_ID = 12819;
	/** Solarflare's orb, nameless and with no options (combat research §11): not an NPC the link holds, but its tile is. */
	public static final int SOLARFLARE_ORB_ID = 12826;

	private final int code;

	NpcKind(int code)
	{
		this.code = code;
	}

	/** The LoS link's type code. */
	public int getCode()
	{
		return code;
	}

	/**
	 * The kind of an NPC by its id, or null for an NPC the link does not hold. A serpent shaman is the reinforcement shaman
	 * when it did not spawn on the wave's first tick.
	 */
	public static NpcKind forNpcId(int npcId, boolean reinforcement)
	{
		switch (npcId)
		{
			case SHAMAN_ID:
				return reinforcement ? REINFORCEMENT_SHAMAN : SERPENT_SHAMAN;
			case JAVELIN_ID:
				return JAVELIN_COLOSSUS;
			case JAGUAR_ID:
				return JAGUAR_WARRIOR;
			case MANTICORE_ID:
				return MANTICORE;
			case MINOTAUR_ID:
			case MINOTAUR_RED_FLAG_ID:
				return MINOTAUR;
			case SHOCKWAVE_ID:
				return SHOCKWAVE_COLOSSUS;
			default:
				return null;
		}
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * A Manticore's orbs in the order they showed, and its LoS link orb code. A Manticore charges its three orbs one after
 * another, each shown as a graphic on it; the order they show in is the order it fires them. Once all three have shown
 * it has charged, and its code is the order alone ("r" and "m" for the two standard orders, whose melee orb comes last,
 * and "Mrm", "Mmr", "rMm" or "mMr" for Mantimayhem III's). Before that its code is "u", uncharged, followed by the order
 * when the orbs seen so far settle it: the first orb does without Mantimayhem III, two orbs do with it.
 */
public final class OrbOrder
{
	private final OrbStyle[] seen = new OrbStyle[3];
	private int count;

	/**
	 * An orb seen on the Manticore this tick. An orb already seen is passed over, since a graphic stays on for several
	 * ticks and the orders repeat once all three have fired.
	 */
	public void see(OrbStyle style)
	{
		if (style == null || count == 3)
		{
			return;
		}
		for (int i = 0; i < count; i++)
		{
			if (seen[i] == style)
			{
				return;
			}
		}
		seen[count++] = style;
	}

	/** How many of the three orbs have shown. */
	public int getCount()
	{
		return count;
	}

	/** The LoS link orb code, with Mantimayhem III on or off. */
	public String losCode(boolean mm3)
	{
		if (count == 3)
		{
			return patternOf(seen[0], seen[1], seen[2]);
		}
		if (count >= 1 && !mm3 && seen[0] != OrbStyle.MELEE)
		{
			// The standard orders put the melee orb last, so the first orb settles the order.
			OrbStyle second = seen[0] == OrbStyle.RANGED ? OrbStyle.MAGIC : OrbStyle.RANGED;
			return "u" + patternOf(seen[0], second, OrbStyle.MELEE);
		}
		if (count == 2 && mm3)
		{
			return "u" + patternOf(seen[0], seen[1], remaining(seen[0], seen[1]));
		}
		return "u";
	}

	private static OrbStyle remaining(OrbStyle a, OrbStyle b)
	{
		for (OrbStyle s : OrbStyle.values())
		{
			if (s != a && s != b)
			{
				return s;
			}
		}
		throw new IllegalArgumentException("two orbs of one style");
	}

	/** The order's name in the LoS link: the first orb's letter for a standard order, all three otherwise. */
	private static String patternOf(OrbStyle first, OrbStyle second, OrbStyle third)
	{
		if (third == OrbStyle.MELEE)
		{
			return String.valueOf(first.getCode());
		}
		return "" + first.getCode() + second.getCode() + third.getCode();
	}
}

