package nl.dexanddice.solsurvivor.core;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;

/**
 * Sol Survivor's state link, version 1, as src/link/statePayload.ts defines it: the site's address, "#s=", and the
 * base64url of a JSON payload, unpadded. The plugin writes the `setup`, the arena as the game shows it, and with the
 * player's gear the `prayer` values and the `equipment`; the site keeps its own kill table and solver settings.
 *
 * The JSON is written by hand, ASCII only and in a fixed order, so that a state always gives the same link and the
 * tests can compare links whole.
 */
public final class StatePayload
{
	/** The payload's version, the site's STATE_VERSION. */
	public static final int VERSION = 1;

	/** The site's state hash, STATE_HASH. */
	public static final String STATE_HASH = "#s=";

	private StatePayload()
	{
	}

	/** The prayer bonus's range the site reads (PRAYER_BONUS_LIMITS); a bonus outside it is clamped to it. */
	private static final int MAX_PRAYER_BONUS = 73;
	/** The most prayer points the site reads (PRAYER_POINTS_LIMITS), the most a level 99 has. */
	private static final int MAX_PRAYER_POINTS = 99;

	/**
	 * Mid-wave: `attacks`, one entry per NPC in the order of `npcs`, each [ticks since its last attack, attacks made] with
	 * null for what the plugin does not know, or null for an NPC it knows nothing of (a Manticore always). Left out when
	 * it knows nothing of any.
	 */
	private static void attacks(StringBuilder b, ArenaState state)
	{
		boolean any = false;
		for (ExportNpc n : state.getNpcs())
		{
			any |= n.getSinceAttack() != null || n.getAttacks() != null;
		}
		if (!any)
		{
			return;
		}
		b.append(",\"attacks\":[");
		boolean first = true;
		for (ExportNpc n : state.getNpcs())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			if (n.getSinceAttack() == null && n.getAttacks() == null)
			{
				b.append("null");
			}
			else
			{
				b.append('[').append(n.getSinceAttack()).append(',').append(n.getAttacks()).append(']');
			}
		}
		b.append(']');
	}

	/** The payload's JSON, without the gear. */
	public static String toJson(ArenaState state)
	{
		return toJson(state, null);
	}

	/** The payload's JSON, with the player's gear and stats when `equipment` is not null. */
	public static String toJson(ArenaState state, Equipment equipment)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"setup\":{\"npcs\":[");
		boolean first = true;
		for (ExportNpc n : state.getNpcs())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(n.getTile().getX()).append(',').append(n.getTile().getY()).append(',').append(n.getKind().getCode());
			if (n.getOrbs() != null)
			{
				b.append(',');
				string(b, n.getOrbs());
			}
			b.append(']');
		}
		b.append("],\"player\":[").append(state.getPlayer().getX()).append(',').append(state.getPlayer().getY()).append(']');
		b.append(",\"waveStart\":").append(state.isWaveStart());
		if (state.isMm3())
		{
			b.append(",\"mm3\":true");
		}
		if (state.getWave() != null)
		{
			b.append(",\"wave\":").append(state.getWave());
		}
		if (!state.isWaveStart())
		{
			// Once the reinforcements have come, none will; before, the plugin gives the tick within the wave and leaves
			// the timer to the site.
			if (state.isReinforcementsArrived())
			{
				b.append(",\"timer\":\"none\"");
			}
			if (state.getWaveTick() != null)
			{
				b.append(",\"waveTick\":").append(state.getWaveTick());
			}
			attacks(b, state);
		}
		b.append(",\"modifiers\":{");
		first = true;
		for (Map.Entry<Modifier, Integer> e : state.getModifiers().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, e.getKey().getKey());
			b.append(':').append(valueOf(e.getKey(), e.getValue()));
		}
		b.append('}');
		if (!state.getSolarflareOrbs().isEmpty())
		{
			b.append(",\"solarflareOrbs\":[");
			first = true;
			for (GridTile t : state.getSolarflareOrbs())
			{
				if (!first)
				{
					b.append(',');
				}
				first = false;
				b.append('[').append(t.getX()).append(',').append(t.getY()).append(']');
			}
			b.append(']');
		}
		b.append('}');
		if (equipment != null)
		{
			gear(b, equipment);
		}
		b.append('}');
		return b.toString();
	}

	/** The `prayer` values the site plans with, and the `equipment` it does not read yet. */
	private static void gear(StringBuilder b, Equipment e)
	{
		b.append(",\"prayer\":{");
		// The site reads 1 to 99 points: with none left, it keeps its own.
		if (e.getPrayerPoints() >= 1)
		{
			b.append("\"start\":").append(Math.min(e.getPrayerPoints(), MAX_PRAYER_POINTS)).append(',');
		}
		b.append("\"bonus\":").append(Math.max(0, Math.min(e.getPrayerBonus(), MAX_PRAYER_BONUS))).append('}');

		b.append(",\"equipment\":{\"items\":{");
		boolean first = true;
		for (Map.Entry<String, Equipment.Item> i : e.getItems().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, i.getKey());
			b.append(":[").append(i.getValue().getId()).append(',');
			string(b, i.getValue().getName());
			b.append(',').append(i.getValue().getQuantity()).append(']');
		}
		b.append('}');
		if (!e.getSwitches().isEmpty())
		{
			// The switches: each [id, name, quantity, slot], in the inventory's order, and a weapon's attack speed after
			// them when it is known.
			b.append(",\"switches\":[");
			for (int i = 0; i < e.getSwitches().size(); i++)
			{
				Equipment.Switch sw = e.getSwitches().get(i);
				if (i > 0)
				{
					b.append(',');
				}
				b.append('[').append(sw.getItem().getId()).append(',');
				string(b, sw.getItem().getName());
				b.append(',').append(sw.getItem().getQuantity()).append(',');
				string(b, sw.getSlot());
				if (sw.getSpeed() > 0)
				{
					b.append(',').append(sw.getSpeed());
				}
				b.append(']');
			}
			b.append(']');
		}
		b.append(",\"weaponSpeed\":").append(e.getWeaponSpeed());
		b.append(",\"weaponCategory\":").append(e.getWeaponCategory());
		b.append(",\"attackStyle\":").append(e.getAttackStyle());
		if (!e.getStyleNames().isEmpty())
		{
			b.append(",\"styleNames\":[");
			for (int i = 0; i < e.getStyleNames().size(); i++)
			{
				if (i > 0)
				{
					b.append(',');
				}
				string(b, e.getStyleNames().get(i));
			}
			b.append(']');
		}
		b.append(",\"stats\":{");
		first = true;
		for (Map.Entry<String, int[]> st : e.getStats().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, st.getKey());
			b.append(":[").append(st.getValue()[0]).append(',').append(st.getValue()[1]).append(']');
		}
		b.append('}');
		if (!e.getBonuses().isEmpty())
		{
			b.append(",\"bonuses\":{");
			first = true;
			for (Map.Entry<Integer, int[]> bonus : e.getBonuses().entrySet())
			{
				if (!first)
				{
					b.append(',');
				}
				first = false;
				b.append('"').append(bonus.getKey()).append("\":[");
				for (int i = 0; i < bonus.getValue().length; i++)
				{
					if (i > 0)
					{
						b.append(',');
					}
					b.append(bonus.getValue()[i]);
				}
				b.append(']');
			}
			b.append('}');
		}
		b.append('}');
	}

	/**
	 * A modifier's value in the link: its tier, true for Dynamic Duo, Red Flag and Totemic, and "random" for Quartet. The
	 * wave log writes its modifiers the same way, so that the site reads both with one reader.
	 */
	static String valueOf(Modifier m, int level)
	{
		switch (m)
		{
			case QUARTET:
				// The engine draws the fourth frem's kind at the wave start, as the game does.
				return "\"random\"";
			case DYNAMIC_DUO:
			case RED_FLAG:
			case TOTEMIC:
				return "true";
			default:
				return String.valueOf(level);
		}
	}

	/**
	 * A JSON string, ASCII only: an item's name may hold any character, which is escaped past ASCII and below a space. The
	 * wave log writes its strings with it too.
	 */
	static void string(StringBuilder b, String s)
	{
		b.append('"');
		for (char c : (s == null ? "" : s).toCharArray())
		{
			if (c == '"' || c == '\\')
			{
				b.append('\\').append(c);
			}
			else if (c < 0x20 || c > 0x7e)
			{
				b.append(String.format("\\u%04x", (int) c));
			}
			else
			{
				b.append(c);
			}
		}
		b.append('"');
	}

	/** The payload's text in a link: its JSON as unpadded base64url. */
	public static String encode(ArenaState state)
	{
		return encode(state, null);
	}

	/** The payload's text in a link, with the player's gear when `equipment` is not null. */
	public static String encode(ArenaState state, Equipment equipment)
	{
		return Base64.getUrlEncoder().withoutPadding().encodeToString(toJson(state, equipment).getBytes(StandardCharsets.US_ASCII));
	}

	/**
	 * The whole link: the site's address, "#s=" and the payload's text. The address loses any hash it had and ends in a
	 * slash.
	 */
	public static String link(String siteUrl, ArenaState state)
	{
		return link(siteUrl, state, null);
	}

	/** The whole link, with the player's gear when `equipment` is not null. */
	public static String link(String siteUrl, ArenaState state, Equipment equipment)
	{
		String base = siteUrl.trim();
		int hash = base.indexOf('#');
		if (hash >= 0)
		{
			base = base.substring(0, hash);
		}
		if (!base.endsWith("/"))
		{
			base += "/";
		}
		return base + STATE_HASH + encode(state, equipment);
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * A tick-by-tick record of one wave as the player played it, for the site's wave reviewer to replay; WaveLogWriter turns
 * it into JSON. Like the rest of the plugin it only reads and exports: nothing here is drawn in the game.
 *
 * The RuneLite layer starts it on the first tick of a wave the tracker saw start, feeds it every hitsplat as it comes and
 * one snapshot of the player and the arena's NPCs each game tick, and finishes it when the wave is completed or the player
 * leaves. The log is kept after that, so that the player can copy it once the wave is over. When the next wave starts,
 * the finished log is kept among the past ones as its JSON, so that any wave since the plugin started can still be
 * copied and reviewed, up to MAX_PAST of them. It holds at most MAX_TICKS ticks, so that a wave left running cannot
 * fill the memory; past that it says it was cut.
 *
 * The animation ids are logged as the game gives them, unfiltered: they are how each NPC's attack animation will be
 * confirmed (an open question in the design spec), so nothing here decides which of them matter.
 */
public final class WaveLog
{
	/** The most ticks a log holds: 15 minutes, far longer than a wave lasts. */
	public static final int MAX_TICKS = 1500;

	/** The most past waves kept besides the one under way: two whole runs. As JSON, each is at most a few hundred kB. */
	public static final int MAX_PAST = 24;

	/** An actor's target when it is interacting with nothing. */
	public static final int TARGET_NONE = -1;
	/** An actor's target when it is interacting with a player, which in the Colosseum is the player themself. */
	public static final int TARGET_PLAYER = -2;

	/** How a wave's log ended: with the game's "Wave N completed!", or with the player leaving the arena. */
	public enum End
	{
		COMPLETED("completed"),
		LEFT("left");

		private final String key;

		End(String key)
		{
			this.key = key;
		}

		/** Its name in the log's JSON. */
		public String getKey()
		{
			return key;
		}
	}

	/** A hitsplat: its amount and the game's hitsplat type id, unfiltered. */
	public static final class Hit
	{
		private final int amount;
		private final int type;

		public Hit(int amount, int type)
		{
			this.amount = amount;
			this.type = type;
		}

		public int getAmount()
		{
			return amount;
		}

		public int getType()
		{
			return type;
		}
	}

	/** The player on one tick. */
	public static final class PlayerTick
	{
		private final GridTile tile;
		private final int hitpoints;
		private final int prayerPoints;
		private final List<String> prayers;
		private final int animation;
		private final int target;
		private final int[] worn;

		/** The player without their gear, as when "Include gear and stats" is off. */
		public PlayerTick(GridTile tile, int hitpoints, int prayerPoints, List<String> prayers, int animation, int target)
		{
			this(tile, hitpoints, prayerPoints, prayers, animation, target, null);
		}

		/**
		 * `tile` is null when the player is off the grid; `prayers` names the prayers on, as prayerName gives them;
		 * `animation` is the game's id, -1 for none; `target` is an NPC's index, TARGET_PLAYER or TARGET_NONE; `worn` is the
		 * item id in each of the link's gear slots, in its order (WORN_SLOTS), -1 for an empty one, or null to leave the gear
		 * out.
		 */
		public PlayerTick(GridTile tile, int hitpoints, int prayerPoints, List<String> prayers, int animation, int target, int[] worn)
		{
			this.tile = tile;
			this.hitpoints = hitpoints;
			this.prayerPoints = prayerPoints;
			this.prayers = Collections.unmodifiableList(new ArrayList<>(prayers));
			this.animation = animation;
			this.target = target;
			this.worn = worn == null ? null : worn.clone();
		}

		public GridTile getTile()
		{
			return tile;
		}

		public int getHitpoints()
		{
			return hitpoints;
		}

		public int getPrayerPoints()
		{
			return prayerPoints;
		}

		public List<String> getPrayers()
		{
			return prayers;
		}

		public int getAnimation()
		{
			return animation;
		}

		public int getTarget()
		{
			return target;
		}

		/** The item ids worn, slot by slot in WORN_SLOTS' order, or null when the gear is left out. */
		public int[] getWorn()
		{
			return worn == null ? null : worn.clone();
		}
	}

	/** An NPC on one tick, any NPC in the arena by its raw id: the waves' NPCs, the frems, Solarflare's orbs and the rest. */
	public static final class NpcTick
	{
		private final int index;
		private final int npcId;
		private final GridTile tile;
		private final int animation;
		private final int healthRatio;
		private final int healthScale;
		private final int target;
		private final int[] spotAnims;

		/** An NPC that shows no graphics. */
		public NpcTick(int index, int npcId, GridTile tile, int animation, int healthRatio, int healthScale, int target)
		{
			this(index, npcId, tile, animation, healthRatio, healthScale, target, new int[0]);
		}

		/**
		 * `tile` is its south-west tile; `animation` is the game's id, -1 for none; the health ratio and scale are as the
		 * game gives them, -1 when unknown; `target` is an NPC's index, TARGET_PLAYER or TARGET_NONE; `spotAnims` are the
		 * ids of the graphics it shows, such as a Manticore's orbs, unfiltered.
		 */
		public NpcTick(int index, int npcId, GridTile tile, int animation, int healthRatio, int healthScale, int target, int[] spotAnims)
		{
			this.index = index;
			this.npcId = npcId;
			this.tile = tile;
			this.animation = animation;
			this.healthRatio = healthRatio;
			this.healthScale = healthScale;
			this.target = target;
			this.spotAnims = spotAnims.clone();
		}

		public int getIndex()
		{
			return index;
		}

		public int getNpcId()
		{
			return npcId;
		}

		public GridTile getTile()
		{
			return tile;
		}

		public int getAnimation()
		{
			return animation;
		}

		public int getHealthRatio()
		{
			return healthRatio;
		}

		public int getHealthScale()
		{
			return healthScale;
		}

		public int getTarget()
		{
			return target;
		}

		/** The ids of the graphics it shows on the tick. */
		public int[] getSpotAnims()
		{
			return spotAnims.clone();
		}
	}

	/**
	 * A past wave's log, kept as its JSON once the next wave started. getRun gives the wave under way or the last one the
	 * same way, as its JSON when it was asked for.
	 */
	public static final class Past
	{
		private final int id;
		private final int wave;
		private final int size;
		private final End end;
		private final String json;

		Past(int id, int wave, int size, End end, String json)
		{
			this.id = id;
			this.wave = wave;
			this.size = size;
			this.end = end;
			this.json = json;
		}

		/** The log's id, as getId gave it while it was the one under way. */
		public int getId()
		{
			return id;
		}

		public int getWave()
		{
			return wave;
		}

		/** How many ticks it holds. */
		public int size()
		{
			return size;
		}

		/** How the wave ended, or null when the next wave started before its end was seen. */
		public End getEnd()
		{
			return end;
		}

		/** The log as WaveLogWriter wrote it. */
		public String getJson()
		{
			return json;
		}
	}

	/** One tick of the wave: the player, the NPCs, the hitsplats that came with it and Solarflare's orbs. */
	static final class Tick
	{
		final int t;
		final PlayerTick player;
		final List<Hit> playerHits;
		final List<NpcTick> npcs;
		/** The hitsplats on NPCs, by NPC index, in the order they came. */
		final Map<Integer, List<Hit>> npcHits;
		final List<GridTile> orbs;
		/**
		 * The animations NPCs started since the last tick, [index, animation id] each, in the order they came. Unlike the
		 * animation an NPC shows on a tick, these mark each start, an attack that repeats the one before included, which
		 * is what times the NPCs' attacks.
		 */
		final List<int[]> animations;
		/** The animations the player started since the last tick, in the order they came: each attack, a repeat included. */
		final List<Integer> playerAnimations;
		/** The item ids worn, on the wave's first tick and on each tick the gear changed; null on the others. */
		final int[] worn;
		/** The graphics the game put on the grid's tiles since the last tick, [x, y, graphic id] each, in the order they came. */
		final List<int[]> tileGraphics;

		Tick(int t, PlayerTick player, List<Hit> playerHits, List<NpcTick> npcs, Map<Integer, List<Hit>> npcHits, List<GridTile> orbs,
			List<int[]> animations, List<Integer> playerAnimations, int[] worn, List<int[]> tileGraphics)
		{
			this.t = t;
			this.player = player;
			this.playerHits = playerHits;
			this.npcs = npcs;
			this.npcHits = npcHits;
			this.orbs = orbs;
			this.animations = animations;
			this.playerAnimations = playerAnimations;
			this.worn = worn;
			this.tileGraphics = tileGraphics;
		}
	}

	/** The gear slots `worn` lists, in its order: those the state link names (Equipment), not the player's look. */
	public static final List<String> WORN_SLOTS = Collections.unmodifiableList(Arrays.asList(
		"head", "cape", "amulet", "weapon", "body", "shield", "legs", "gloves", "boots", "ring", "ammo"));

	private Integer wave;
	private int startTick;
	private Map<Modifier, Integer> modifiers = new EnumMap<>(Modifier.class);
	private boolean modifiersComplete;
	private String version = "";
	/** The state link's payload on the wave's first tick, as StatePayload wrote it, or null when it could not be taken. */
	private String startState;
	private final List<Tick> ticks = new ArrayList<>();
	private boolean cut;
	private End end;
	private boolean recording;
	/** The log's id, which tells it apart from the past ones, and the last id given. */
	private int id;
	private int lastId;
	/** The past waves' logs, newest first. */
	private final List<Past> past = new ArrayList<>();
	/** The gear worn on the last tick recorded, so that a tick lists it only when it changed. */
	private int[] lastWorn;

	/** The hitsplats since the last tick was recorded, which go in the next one. */
	private final List<Hit> pendingPlayerHits = new ArrayList<>();
	private final Map<Integer, List<Hit>> pendingNpcHits = new LinkedHashMap<>();
	/** The animations NPCs started since the last tick was recorded, which go in the next one. */
	private final List<int[]> pendingAnimations = new ArrayList<>();
	/** The animations the player started since the last tick was recorded. */
	private final List<Integer> pendingPlayerAnimations = new ArrayList<>();
	/** The graphics put on tiles since the last tick was recorded. */
	private final List<int[]> pendingTileGraphics = new ArrayList<>();

	/**
	 * A wave starts on game tick `gameTick`: the last wave's log goes among the past ones, and the log records this one.
	 * `startState` is the state link's payload on this tick (StatePayload.toJson), or null. The hitsplats already passed on
	 * this tick are kept for it.
	 */
	public void start(int wave, int gameTick, Map<Modifier, Integer> modifiers, boolean modifiersComplete, String version, String startState)
	{
		if (this.wave != null)
		{
			past.add(0, new Past(id, this.wave, ticks.size(), end, WaveLogWriter.toJson(this)));
			while (past.size() > MAX_PAST)
			{
				past.remove(past.size() - 1);
			}
		}
		this.wave = wave;
		this.startTick = gameTick;
		this.modifiers = new EnumMap<>(Modifier.class);
		this.modifiers.putAll(modifiers);
		this.modifiersComplete = modifiersComplete;
		this.version = version;
		this.startState = startState;
		ticks.clear();
		cut = false;
		end = null;
		recording = true;
		id = ++lastId;
		lastWorn = null;
	}

	/** A hitsplat on the player, as it comes; it goes in the next tick recorded. */
	public void onPlayerHit(int amount, int type)
	{
		pendingPlayerHits.add(new Hit(amount, type));
	}

	/** A hitsplat on the NPC at `index`, as it comes; it goes in the next tick recorded. */
	public void onNpcHit(int index, int amount, int type)
	{
		pendingNpcHits.computeIfAbsent(index, i -> new ArrayList<>()).add(new Hit(amount, type));
	}

	/** An NPC started an animation, as it comes; it goes in the next tick recorded. */
	public void onNpcAnimation(int index, int animation)
	{
		pendingAnimations.add(new int[] {index, animation});
	}

	/** The player started an animation, as it comes; it goes in the next tick recorded. */
	public void onPlayerAnimation(int animation)
	{
		pendingPlayerAnimations.add(animation);
	}

	/**
	 * The game put a graphic on a tile, such as where a Javelin Colossus's special lands, as it comes; it goes in the next
	 * tick recorded. One off the grid, or with no tile, is left out.
	 */
	public void onTileGraphic(GridTile tile, int graphic)
	{
		if (tile != null && ArenaGeometry.onGrid(tile))
		{
			pendingTileGraphics.add(new int[] {tile.getX(), tile.getY(), graphic});
		}
	}

	/**
	 * Game tick `gameTick` of the wave: the player and every NPC the game shows. NPCs off the grid are left out, and the
	 * tiles of Solarflare's orbs are taken from the orb NPCs. The player's gear is kept for the tick only when it changed
	 * since the tick before. A tick already recorded, or one past MAX_TICKS, is passed over; either way the hitsplats since
	 * the last tick are used up.
	 */
	public void record(int gameTick, PlayerTick player, List<NpcTick> npcs)
	{
		if (!recording)
		{
			discardPending();
			return;
		}
		int t = gameTick - startTick;
		if (!ticks.isEmpty() && ticks.get(ticks.size() - 1).t >= t)
		{
			discardPending();
			return;
		}
		if (ticks.size() >= MAX_TICKS)
		{
			cut = true;
			discardPending();
			return;
		}
		List<NpcTick> onGrid = new ArrayList<>();
		List<GridTile> orbs = new ArrayList<>();
		for (NpcTick n : npcs)
		{
			if (n.getTile() == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			onGrid.add(n);
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID)
			{
				orbs.add(n.getTile());
			}
		}
		Map<Integer, List<Hit>> npcHits = new LinkedHashMap<>();
		for (Map.Entry<Integer, List<Hit>> e : pendingNpcHits.entrySet())
		{
			npcHits.put(e.getKey(), Collections.unmodifiableList(new ArrayList<>(e.getValue())));
		}
		int[] worn = player == null ? null : player.getWorn();
		int[] changed = worn != null && !Arrays.equals(worn, lastWorn) ? worn : null;
		if (worn != null)
		{
			lastWorn = worn;
		}
		ticks.add(new Tick(t, player, Collections.unmodifiableList(new ArrayList<>(pendingPlayerHits)), Collections.unmodifiableList(onGrid),
			Collections.unmodifiableMap(npcHits), Collections.unmodifiableList(orbs), Collections.unmodifiableList(new ArrayList<>(pendingAnimations)),
			Collections.unmodifiableList(new ArrayList<>(pendingPlayerAnimations)), changed, Collections.unmodifiableList(new ArrayList<>(pendingTileGraphics))));
		discardPending();
	}

	/** Forget the hitsplats since the last tick: the RuneLite layer calls this on each tick it does not record. */
	public void discardPending()
	{
		pendingPlayerHits.clear();
		pendingNpcHits.clear();
		pendingAnimations.clear();
		pendingPlayerAnimations.clear();
		pendingTileGraphics.clear();
	}

	/** The wave ended: the log stops recording and is kept until the next wave starts. */
	public void finish(End how)
	{
		if (recording)
		{
			recording = false;
			end = how;
		}
		discardPending();
	}

	/** Forget the log and the past ones altogether: the plugin or its log was switched off. */
	public void clear()
	{
		wave = null;
		ticks.clear();
		cut = false;
		end = null;
		recording = false;
		modifiers = new EnumMap<>(Modifier.class);
		modifiersComplete = false;
		version = "";
		startState = null;
		id = 0;
		lastWorn = null;
		past.clear();
		discardPending();
	}

	/** Whether a wave is being recorded. */
	public boolean isRecording()
	{
		return recording;
	}

	/** Whether there is a log to copy: a wave was started, while recording or after. */
	public boolean hasLog()
	{
		return wave != null;
	}

	/** The log's id, given when its wave started, or 0 when there is none. */
	public int getId()
	{
		return id;
	}

	/** The past waves' logs, newest first. */
	public List<Past> getPast()
	{
		return Collections.unmodifiableList(past);
	}

	/**
	 * The newest run's logs, oldest first, for RunLogWriter: the newest log, the wave under way or the last one, and going
	 * back from it each log whose wave is the one before the wave of the log after it. The run starts at wave 1, which has
	 * no wave before it, so that it never reaches back into the run before; or, when the plugin did not log the run from
	 * wave 1, such as when it started mid-run, at the oldest wave of the series it logged. A wave missing from the series
	 * or logged twice parts it there, and the run is the newer part. How a wave ended does not part a run: the next run
	 * starts at wave 1 again, which parts the two already. The past waves kept, MAX_PAST, are more than a run's 12 waves
	 * (wave 12 is Sol Heredit's), so that a run is always whole. Each log is as Copy wave log copies it: a past one as
	 * its JSON, and the newest as WaveLogWriter writes it now. Empty when there is no log.
	 */
	public List<Past> getRun()
	{
		List<Past> run = new ArrayList<>();
		if (wave == null)
		{
			return run;
		}
		run.add(new Past(id, wave, ticks.size(), end, WaveLogWriter.toJson(this)));
		int next = wave;
		for (Past p : past)
		{
			if (p.getWave() != next - 1)
			{
				break;
			}
			run.add(0, p);
			next = p.getWave();
		}
		return Collections.unmodifiableList(run);
	}

	/** The wave logged, or null when there is none. */
	public Integer getWave()
	{
		return wave;
	}

	/** How many ticks the log holds. */
	public int size()
	{
		return ticks.size();
	}

	/** Whether ticks were left out because the log was full. */
	public boolean isCut()
	{
		return cut;
	}

	/** How the wave ended, or null while it is under way or when the log was never finished. */
	public End getEnd()
	{
		return end;
	}

	Map<Modifier, Integer> getModifiers()
	{
		return Collections.unmodifiableMap(modifiers);
	}

	boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	String getVersion()
	{
		return version;
	}

	String getStartState()
	{
		return startState;
	}

	List<Tick> getTicks()
	{
		return Collections.unmodifiableList(ticks);
	}

	/**
	 * A prayer's name in the log, from the name of RuneLite's Prayer constant: the three protection prayers are "magic",
	 * "ranged" and "melee", as the site names them, and every other prayer is its constant's name in lower case, such as
	 * "piety" or "rp_ancient_strength".
	 */
	public static String prayerName(String prayerConstant)
	{
		switch (prayerConstant)
		{
			case "PROTECT_FROM_MAGIC":
				return "magic";
			case "PROTECT_FROM_MISSILES":
				return "ranged";
			case "PROTECT_FROM_MELEE":
				return "melee";
			default:
				return prayerConstant.toLowerCase(Locale.ROOT);
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The wave log's JSON, for the site's log checker (src/viewer/waveLogCheck.ts). Like StatePayload it is written by
 * hand, ASCII only and in a fixed order, so that a log always gives the same text and the tests can compare it whole;
 * each tick is on a line of its own, so that a log reads and diffs a tick at a time.
 *
 * <pre>
 * {"v":1,"kind":"solSurvivorWaveLog","plugin":"0.2.0","wave":4,
 *  "modifiers":{"reentry":2,"quartet":"random"},"modifiersComplete":true,
 *  "maxTicks":1500,"cut":false,"end":"completed","start":{"v":1,"setup":{...}},"ticks":[
 * {"t":0,"player":[7,15,99,77,["magic","piety"],-1,null],"hits":[],
 *  "npcs":[[11,12811,13,20,-1,-1,-1,"player",[]],[12,12818,16,24,7590,30,30,"player",[[0,12]]]],"orbs":[],
 *  "worn":[26382,21295,-1,20997,26384,-1,26386,-1,-1,-1,-1]},
 * {"t":1,...,"anims":[[11,10859]],"playerAnims":[426],"spots":[[12,2681]]},
 * ...
 * ]}
 * </pre>
 *
 * <ul>
 * <li>`v`: the log's version, 1; `kind`: always "solSurvivorWaveLog", which tells it apart from a state link's payload;
 * `plugin`: the plugin's version.</li>
 * <li>`wave`: the wave, 1 to 11, or 12 for Sol Heredit's.</li>
 * <li>`modifiers`: the modifiers taken at the wave's start, written as the state link writes them (its tier, true or
 * "random"); `modifiersComplete`: whether Quartet, Red Flag and Totemic are known (see ArenaState).</li>
 * <li>`maxTicks`: the most ticks a log holds; `cut`: whether the wave ran past it and the rest was left out.</li>
 * <li>`end`: "completed" when the game said the wave was completed, "left" when the player left the arena (died, ran or
 * logged out), null while the wave is under way, or when the next wave started before its end was seen.</li>
 * <li>`start`: the state link's payload on the wave's first tick (StatePayload, the site's src/link/statePayload.ts),
 * with the gear and stats when "Include gear and stats" is on, so that the site can plan the wave from where it began
 * and put the plan beside what the player did; null when it could not be taken.</li>
 * <li>`ticks`: one object a game tick, from the wave's first tick on:
 * <ul>
 * <li>`t`: the tick within the wave, 0 on the tick of the game's "Wave: N" message;</li>
 * <li>`player`: [x, y, hitpoints, prayer points, [prayers on], animation id, target], with x and y the grid tile (null
 * off the grid), the prayers as WaveLog.prayerName names them, -1 for no animation, and the target an NPC's index,
 * "player" or null;</li>
 * <li>`hits`: the hitsplats on the player that came with this tick, [amount, hitsplat type id] each;</li>
 * <li>`npcs`: every NPC on the grid, by its raw id: [index, NPC id, x, y, animation id, health ratio, health scale,
 * target, [hitsplats]], with x and y its south-west tile, -1 for no animation and for an unknown health ratio or scale,
 * the target as the player's, and its hitsplats this tick as the player's;</li>
 * <li>`orbs`: the tiles of Solarflare's orbs (NPC 12826), [x, y] each, which are in `npcs` too;</li>
 * <li>`strayHits`, only when there are any: hitsplats on an NPC that is not in `npcs` this tick, [index, amount, type]
 * each;</li>
 * <li>`anims`, only when there are any: the animations NPCs started since the tick before, [index, animation id] each,
 * in the order they came. Each start is there, an attack that repeats the one before included, where the animation in
 * `npcs` only shows what an NPC is doing on the tick. An NPC whose animation stops is there too, with -1.</li>
 * <li>`playerAnims`, only when there are any: the animations the player started since the tick before, as `anims` has
 * the NPCs', so that each of the player's attacks is there even when the weapon's animation runs on unbroken.</li>
 * <li>`spots`, only when there are any: the graphics the NPCs in `npcs` show on the tick, [index, graphic id] each, such
 * as a Manticore's orbs as it charges them, unfiltered.</li>
 * <li>`worn`, on the wave's first tick and on each tick the player's gear changed, when "Include gear and stats" is on:
 * the item id in each slot of WaveLog.WORN_SLOTS, in its order, -1 for an empty one.</li>
 * <li>`tileGraphics`, only when there are any: the graphics the game put on the grid's tiles since the tick before,
 * [x, y, graphic id] each, in the order they came, unfiltered, such as where a Javelin Colossus's special lands.</li>
 * </ul>
 * </li>
 * </ul>
 * The hitsplats of a tick are those the game showed since the tick before, which RuneLite passes on between ticks.
 */
public final class WaveLogWriter
{
	/** The log's version. */
	public static final int VERSION = 1;

	/** The log's `kind`. */
	public static final String KIND = "solSurvivorWaveLog";

	private WaveLogWriter()
	{
	}

	/** The log's JSON; an empty log, with no wave, has a null wave and no ticks. */
	public static String toJson(WaveLog log)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"kind\":");
		StatePayload.string(b, KIND);
		b.append(",\"plugin\":");
		StatePayload.string(b, log.getVersion());
		b.append(",\"wave\":").append(log.getWave());
		b.append(",\"modifiers\":{");
		boolean first = true;
		for (Map.Entry<Modifier, Integer> e : log.getModifiers().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			StatePayload.string(b, e.getKey().getKey());
			b.append(':').append(StatePayload.valueOf(e.getKey(), e.getValue()));
		}
		b.append("},\"modifiersComplete\":").append(log.isModifiersComplete());
		b.append(",\"maxTicks\":").append(WaveLog.MAX_TICKS);
		b.append(",\"cut\":").append(log.isCut());
		b.append(",\"end\":");
		if (log.getEnd() == null)
		{
			b.append("null");
		}
		else
		{
			StatePayload.string(b, log.getEnd().getKey());
		}
		b.append(",\"start\":").append(log.getStartState() == null ? "null" : log.getStartState());
		b.append(",\"ticks\":[");
		first = true;
		for (WaveLog.Tick tick : log.getTicks())
		{
			b.append(first ? "\n" : ",\n");
			first = false;
			tick(b, tick);
		}
		b.append(first ? "]}" : "\n]}");
		return b.toString();
	}

	private static void tick(StringBuilder b, WaveLog.Tick tick)
	{
		b.append("{\"t\":").append(tick.t).append(",\"player\":");
		WaveLog.PlayerTick p = tick.player;
		if (p == null)
		{
			b.append("null");
		}
		else
		{
			b.append('[');
			tile(b, p.getTile());
			b.append(',').append(p.getHitpoints()).append(',').append(p.getPrayerPoints()).append(",[");
			boolean first = true;
			for (String prayer : p.getPrayers())
			{
				if (!first)
				{
					b.append(',');
				}
				first = false;
				StatePayload.string(b, prayer);
			}
			b.append("],").append(p.getAnimation()).append(',');
			target(b, p.getTarget());
			b.append(']');
		}
		b.append(",\"hits\":");
		hits(b, tick.playerHits);

		b.append(",\"npcs\":[");
		boolean first = true;
		for (WaveLog.NpcTick n : tick.npcs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(n.getIndex()).append(',').append(n.getNpcId()).append(',');
			tile(b, n.getTile());
			b.append(',').append(n.getAnimation()).append(',').append(n.getHealthRatio()).append(',').append(n.getHealthScale()).append(',');
			target(b, n.getTarget());
			b.append(',');
			hits(b, tick.npcHits.getOrDefault(n.getIndex(), Collections.emptyList()));
			b.append(']');
		}
		b.append("],\"orbs\":[");
		first = true;
		for (GridTile t : tick.orbs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(t.getX()).append(',').append(t.getY()).append(']');
		}
		b.append(']');

		// Hitsplats on an NPC the tick does not list, such as one that despawned before the tick's snapshot, are kept.
		StringBuilder stray = new StringBuilder();
		for (Map.Entry<Integer, List<WaveLog.Hit>> e : tick.npcHits.entrySet())
		{
			if (listed(tick.npcs, e.getKey()))
			{
				continue;
			}
			for (WaveLog.Hit h : e.getValue())
			{
				stray.append(stray.length() == 0 ? "" : ",").append('[').append(e.getKey()).append(',').append(h.getAmount()).append(',')
					.append(h.getType()).append(']');
			}
		}
		if (stray.length() > 0)
		{
			b.append(",\"strayHits\":[").append(stray).append(']');
		}
		if (!tick.animations.isEmpty())
		{
			b.append(",\"anims\":[");
			for (int i = 0; i < tick.animations.size(); i++)
			{
				int[] a = tick.animations.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(a[0]).append(',').append(a[1]).append(']');
			}
			b.append(']');
		}
		if (!tick.playerAnimations.isEmpty())
		{
			b.append(",\"playerAnims\":[");
			for (int i = 0; i < tick.playerAnimations.size(); i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.playerAnimations.get(i));
			}
			b.append(']');
		}
		StringBuilder spots = new StringBuilder();
		for (WaveLog.NpcTick n : tick.npcs)
		{
			for (int id : n.getSpotAnims())
			{
				spots.append(spots.length() == 0 ? "" : ",").append('[').append(n.getIndex()).append(',').append(id).append(']');
			}
		}
		if (spots.length() > 0)
		{
			b.append(",\"spots\":[").append(spots).append(']');
		}
		if (tick.worn != null)
		{
			b.append(",\"worn\":[");
			for (int i = 0; i < tick.worn.length; i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.worn[i]);
			}
			b.append(']');
		}
		if (!tick.tileGraphics.isEmpty())
		{
			b.append(",\"tileGraphics\":[");
			for (int i = 0; i < tick.tileGraphics.size(); i++)
			{
				int[] g = tick.tileGraphics.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(g[0]).append(',').append(g[1]).append(',').append(g[2]).append(']');
			}
			b.append(']');
		}
		b.append('}');
	}

	private static boolean listed(List<WaveLog.NpcTick> npcs, int index)
	{
		for (WaveLog.NpcTick n : npcs)
		{
			if (n.getIndex() == index)
			{
				return true;
			}
		}
		return false;
	}

	/** A tile as two numbers, x and y, or two nulls for none. */
	private static void tile(StringBuilder b, GridTile t)
	{
		if (t == null)
		{
			b.append("null,null");
		}
		else
		{
			b.append(t.getX()).append(',').append(t.getY());
		}
	}

	private static void target(StringBuilder b, int target)
	{
		if (target == WaveLog.TARGET_PLAYER)
		{
			b.append("\"player\"");
		}
		else if (target < 0)
		{
			b.append("null");
		}
		else
		{
			b.append(target);
		}
	}

	private static void hits(StringBuilder b, List<WaveLog.Hit> hits)
	{
		b.append('[');
		boolean first = true;
		for (WaveLog.Hit h : hits)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(h.getAmount()).append(',').append(h.getType()).append(']');
		}
		b.append(']');
	}
}

package nl.dexanddice.solsurvivor;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Starts RuneLite with the plugin loaded, for trying it in game: ./gradlew run. */
